adcs_vec3_t vec_part;
double w_clamped, angle, vec_norm;

/* Check for NULL pointers */
if ((predicted == NULL) || (measured == NULL) || 
    (rotation_vector == NULL) || (angle == NULL)) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
    *angle = INFINITY;
    return ADCS_E_NULL;
}

/* Normalize predicted quaternion */
if (adcs_quat_normalize(predicted, &pred_norm) != ADCS_OK) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
    *angle = INFINITY;
    return ADCS_E_DEGENERATE;
}

/* Normalize measured quaternion */
if (adcs_quat_normalize(measured, &meas_norm) != ADCS_OK) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
    *angle = INFINITY;
    return ADCS_E_DEGENERATE;
}

/* Compute relative quaternion: q_rel = measured * conjugate(predicted) */
adcs_quat_t conj_pred = adcs_quat_conjugate(&pred_norm);
q_rel = adcs_quat_multiply(&meas_norm, &conj_pred);

/* Canonicalize: negate if scalar part is negative */
if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

/* Calculate angle: 2 * acos(clamped_w) */
w_clamped = ADCS_CLAMP(q_rel.w, 0.0, 1.0);
*angle = 2.0 * acos(w_clamped);

/* Calculate rotation vector */
vec_part.x = q_rel.x;
vec_part.y = q_rel.y;
vec_part.z = q_rel.z;
vec_norm = adcs_vec3_norm(&vec_part);

if (vec_norm <= ADCS_EPS_NORM) {
    /* Vector norm is negligible, rotation vector is zero */
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
} else {
    /* rotation_vector = angle * (vector / ||vector||) */
    adcs_vec3_t unit_vec = adcs_vec3_scale(&vec_part, 1.0 / vec_norm);
    *rotation_vector = adcs_vec3_scale(&unit_vec, *angle);
}

